// Package scan finds byte-identical regular files in a directory tree.
package scan

import (
	"crypto/sha256"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Group describes files with the same size and content digest.
type Group struct {
	Size   int64
	SHA256 string
	Paths  []string
}

// Scan walks root without following symbolic links. Files that cannot be read
// are skipped with a warning; traversal errors are returned.
func Scan(root string, minSize int64, warnings io.Writer) ([]Group, error) {
	bySize := make(map[int64][]string)
	err := filepath.WalkDir(root, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.Type()&os.ModeSymlink != 0 {
			return nil
		}
		if entry.IsDir() {
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		if !info.Mode().IsRegular() || info.Size() < minSize {
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		bySize[info.Size()] = append(bySize[info.Size()], filepath.ToSlash(rel))
		return nil
	})
	if err != nil {
		return nil, err
	}
	var groups []Group
	for size, paths := range bySize {
		if len(paths) < 2 {
			continue
		}
		byDigest := make(map[string][]string)
		for _, rel := range paths {
			f, err := os.Open(filepath.Join(root, filepath.FromSlash(rel)))
			if err != nil {
				if warnings != nil {
					fmt.Fprintf(warnings, "warning: cannot read %s: %v\n", rel, err)
				}
				continue
			}
			h := sha256.New()
			_, readErr := io.Copy(h, f)
			closeErr := f.Close()
			if readErr != nil || closeErr != nil {
				if warnings != nil {
					cause := readErr
					if cause == nil {
						cause = closeErr
					}
					fmt.Fprintf(warnings, "warning: cannot read %s: %v\n", rel, cause)
				}
				continue
			}
			byDigest[fmt.Sprintf("%x", h.Sum(nil))] = append(byDigest[fmt.Sprintf("%x", h.Sum(nil))], rel)
		}
		for digest, matches := range byDigest {
			if len(matches) >= 2 {
				groups = append(groups, Group{Size: size, SHA256: digest, Paths: matches})
			}
		}
	}
	return groups, nil
}

// NormalizePaths is retained as a small utility for consumers constructing groups.
func NormalizePaths(paths []string) {
	sort.Slice(paths, func(i, j int) bool { return strings.Compare(paths[i], paths[j]) < 0 })
}
// Package cli implements dupfind's command-line contract.
package cli

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strconv"

	"dupfind/internal/output"
	"dupfind/internal/scan"
)

// Run executes dupfind with args and writes command output to stdout and stderr.
func Run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("dupfind", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	summary := fs.Bool("summary", false, "write duplicate totals instead of a file listing")
	minText := fs.String("min-size", "1", "minimum file size in bytes (positive integer)")
	printHelp := func() {
		fmt.Fprintln(stdout, "dupfind finds exact duplicate regular files in a directory tree.")
		fmt.Fprintln(stdout, "Usage: dupfind [--summary] [--min-size <bytes>] <directory>")
		fmt.Fprintln(stdout, "Options:")
		fmt.Fprintln(stdout, "  --summary           write duplicate group and reclaimable-space totals")
		fmt.Fprintln(stdout, "  --min-size <bytes>  ignore files smaller than this positive size (default: 1)")
	}
	fs.Usage = func() {}
	if err := fs.Parse(args); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			printHelp()
			return 0
		}
		fmt.Fprintln(stderr, "error: invalid command options")
		return 2
	}
	minSize, err := strconv.ParseInt(*minText, 10, 64)
	if err != nil || minSize <= 0 {
		fmt.Fprintln(stderr, "error: --min-size must be a positive integer")
		return 2
	}
	if fs.NArg() != 1 {
		fmt.Fprintln(stderr, "error: exactly one directory argument is required")
		return 2
	}
	root := fs.Arg(0)
	info, err := os.Stat(root)
	if err != nil {
		fmt.Fprintf(stderr, "error: cannot access directory %s: %v\n", root, err)
		return 1
	}
	if !info.IsDir() {
		fmt.Fprintf(stderr, "error: path is not a directory: %s\n", root)
		return 1
	}
	groups, err := scan.Scan(root, minSize, stderr)
	if err != nil {
		fmt.Fprintf(stderr, "error: cannot scan directory %s: %v\n", root, err)
		return 1
	}
	if *summary {
		if err := output.Summary(stdout, groups); err != nil {
			fmt.Fprintf(stderr, "error: cannot write output: %v\n", err)
			return 1
		}
	} else if err := output.Listing(stdout, groups); err != nil {
		fmt.Fprintf(stderr, "error: cannot write output: %v\n", err)
		return 1
	}
	return 0
}

// Package output formats deterministic CSV results.
package output

import (
	"encoding/csv"
	"fmt"
	"io"
	"sort"

	"dupfind/internal/scan"
)

// Ordered returns a sorted copy of groups, with paths sorted by byte order.
func Ordered(groups []scan.Group) []scan.Group {
	out := make([]scan.Group, len(groups))
	copy(out, groups)
	for i := range out {
		out[i].Paths = append([]string(nil), out[i].Paths...)
		sort.Slice(out[i].Paths, func(a, b int) bool { return out[i].Paths[a] < out[i].Paths[b] })
	}
	sort.Slice(out, func(i, j int) bool {
		a := out[i].Size * int64(len(out[i].Paths)-1)
		b := out[j].Size * int64(len(out[j].Paths)-1)
		if a != b {
			return a > b
		}
		return out[i].SHA256 < out[j].SHA256
	})
	return out
}

// Listing writes the duplicate listing CSV.
func Listing(w io.Writer, groups []scan.Group) error {
	c := csv.NewWriter(w)
	if err := c.Write([]string{"group", "size", "sha256", "path"}); err != nil {
		return err
	}
	for i, g := range Ordered(groups) {
		for _, p := range g.Paths {
			if err := c.Write([]string{fmt.Sprint(i + 1), fmt.Sprint(g.Size), g.SHA256, p}); err != nil {
				return err
			}
		}
	}
	c.Flush()
	return c.Error()
}

// Summary writes group, duplicate-file, and reclaimable-byte totals.
func Summary(w io.Writer, groups []scan.Group) error {
	c := csv.NewWriter(w)
	ordered := Ordered(groups)
	var duplicates, reclaimable int64
	for _, g := range ordered {
		copies := int64(len(g.Paths) - 1)
		duplicates += copies
		reclaimable += g.Size * copies
	}
	if err := c.Write([]string{"groups", "duplicate_files", "reclaimable_bytes"}); err != nil {
		return err
	}
	if err := c.Write([]string{fmt.Sprint(len(ordered)), fmt.Sprint(duplicates), fmt.Sprint(reclaimable)}); err != nil {
		return err
	}
	c.Flush()
	return c.Error()
}
